import{_ as n,a0 as p,w as o,s as d,ao as r,I as i,x as e,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"awk 系列：如何讓 awk 使用 Shell 變量 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何讓 awk 使用 Shell 變量 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何讓 awk 使用 Shell 變量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何讓 awk 使用 Shell 變量 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 11 - How to Allow Awk to Use Shell Variables","title":"awk 系列：如何讓 awk 使用 Shell 變量","tag":"awk","desc":""},"relativePath":"awk/Part 11 - How to Allow Awk to Use Shell Variables.md","filePath":"[post].md"}'),h={name:"awk/Part 11 - How to Allow Awk to Use Shell Variables.md"};function k(w,a,c,u,m,g){const s=p("Link");return o(),d("div",null,[a[13]||(a[13]=r(`<h1 id="awk-系列-如何讓-awk-使用-shell-變量" tabindex="-1">awk 系列：如何讓 awk 使用 Shell 變量 <a class="header-anchor" href="#awk-系列-如何讓-awk-使用-shell-變量" aria-label="Permalink to “awk 系列：如何讓 awk 使用 Shell 變量”">​</a></h1><p>當我們編寫 shell 腳本時，我們通常會在腳本中包含其它小程序或命令，例如 awk 操作。對於 awk 而言，我們需要找一些將某些值從 shell 傳遞到 awk 操作中的方法。</p><p>我們可以通過在 awk 命令中使用 shell 變量達到目的，在 awk 系列的這一節中，我們將學習如何讓 awk 使用 shell 變量，這些變量可能包含我們希望傳遞給 awk 命令的值。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Use-Shell-Variables-in-Awk.png" alt=""></p><p>有兩種可能的方法可以讓 awk 使用 shell 變量：</p><h3 id="_1-使用-shell-引用" tabindex="-1">1. 使用 Shell 引用 <a class="header-anchor" href="#_1-使用-shell-引用" aria-label="Permalink to “1. 使用 Shell 引用”">​</a></h3><p>讓我們用一個示例來演示如何在一條 awk 命令中使用 shell 引用來替代一個 shell 變量。在該示例中，我們希望在文件 /etc/passwd 中搜索一個用户名，過濾並輸出用户的賬户信息。</p><p>因此，我們可以編寫一個 <code>test.sh</code> 腳本，內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 讀取用户名</span></span>
<span class="line"><span>read -p &quot;請輸入用户名：&quot; username</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 在 /etc/passwd 中搜索用户名，然後在屏幕上輸出詳細信息</span></span>
<span class="line"><span>cat /etc/passwd | awk &quot;/$username/ &quot;&#39; { print $0 }&#39;</span></span></code></pre></div><p>然後，保存文件並退出。</p><p>上述 <code>test.sh</code> 腳本中 awk 命令的説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/passwd | awk &quot;/$username/ &quot;&#39; { print $0 }&#39;</span></span></code></pre></div><p><code>&quot;/$username/ &quot;</code>：該 shell 引用用於在 awk 命令中替換 shell 變量 <code>username</code> 的值。<code>username</code> 的值就是要在文件 /etc/passwd 中搜索的模式。</p><p>注意，雙引號位於 awk 腳本 <code>&#39;{ print $0 }&#39;</code> 之外。</p><p>接下來給腳本添加可執行權限並運行它，操作如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod  +x  test.sh</span></span>
<span class="line"><span>$ ./text.sh</span></span></code></pre></div><p>運行腳本後，它會提示你輸入一個用户名，然後你輸入一個合法的用户名並回車。你將會看到來自 /etc/passwd 文件中詳細的用户賬户信息，如下圖所示：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Shell-Script-to-Find-Username-in-Passwd-File.png" alt=""></p><p><em>在 Password 文件中查找用户名的 shell 腳本</em></p><h3 id="_2-使用-awk-進行變量賦值" tabindex="-1">2. 使用 awk 進行變量賦值 <a class="header-anchor" href="#_2-使用-awk-進行變量賦值" aria-label="Permalink to “2. 使用 awk 進行變量賦值”">​</a></h3><p>和上面介紹的方法相比，該方法更加單，並且更好。考慮上面的示例，我們可以運行一條簡單的命令來完成同樣的任務。 在該方法中，我們使用 <code>-v</code> 選項將一個 shell 變量的值賦給一個 awk 變量。</p><p>首先，創建一個 shell 變量 <code>username</code>，然後給它賦予一個我們希望在 /etc/passwd 文件中搜索的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>username=&quot;aaronkilik&quot;</span></span></code></pre></div><p>然後輸入下面的命令並回車：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/passwd | awk -v name=&quot;$username&quot; &#39; $0 ~ name {print $0}&#39;</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Find-Username-in-Password-File-Using-Awk.png" alt=""></p><p><em>使用 awk 在 Password 文件中查找用户名</em></p><p>上述命令的説明：</p><ul><li><code>-v</code>：awk 選項之一，用於聲明一個變量</li><li><code>username</code>：是 shell 變量</li><li><code>name</code>：是 awk 變量</li></ul><p>讓我們仔細瞧瞧 awk 腳本 <code>&#39; $0 ~ name {print $0}&#39;</code> 中的 <code>$0 ~ name</code>。還記得麼，當我們在 awk 系列第四節中介紹 awk 比較運算符時，<code>value ~ pattern</code> 便是比較運算符之一，它是指：如果 <code>value</code> 匹配了 <code>pattern</code> 則返回 <code>true</code>。</p><p>cat 命令通過管道傳給 awk 的 <code>output($0)</code> 與模式 <code>(aaronkilik)</code> 匹配，該模式即為我們在 /etc/passwd 中搜索的名稱，最後，比較操作返回 <code>true</code>。接下來會在屏幕上輸出包含用户賬户信息的行。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我們已經介紹了 awk 功能的一個重要部分，它能幫助我們在 awk 命令中使用 shell 變量。很多時候，你都會在 shell 腳本中編寫小的 awk 程序或命令，因此，你需要清晰地理解如何在 awk 命令中使用 shell 變量。</p><p>在 awk 系列的下一個部分，我們將會深入學習 awk 功能的另外一個關鍵部分，即流程控制語句。所以請繼續保持關注，並讓我們堅持學習與分享。</p><hr>`,35)),i("p",null,[a[1]||(a[1]=e("via: ",-1)),t(s,{href:"http://www.tecmint.com/use-shell-script-variable-in-awk/"},{default:l(()=>[...a[0]||(a[0]=[e("http://www.tecmint.com/use-shell-script-variable-in-awk/",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=e("作者：",-1)),t(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:l(()=>[...a[2]||(a[2]=[e("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=e(" 譯者：",-1)),t(s,{href:"https://github.com/chrisleegit"},{default:l(()=>[...a[3]||(a[3]=[e("ChrisLeeGit",-1)])]),_:1}),a[7]||(a[7]=e(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...a[9]||(a[9]=[e("Linux中國",-1)])]),_:1}),a[12]||(a[12]=e(" 榮譽推出",-1))])])}const x=n(h,[["render",k]]);export{C as __pageData,x as default};
